// Bundles tools/collector into worker/generated/collector-bundle.ts so the Worker can serve it as a zip.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
const dir = 'tools/collector';
const names = ['collect.cmd', 'tereflow_collect.py', 'requirements.txt', 'iso3_m49.json', 'partner_iso3.json', 'README.txt'];
const files = Object.fromEntries(names.map((n) => [n, readFileSync(`${dir}/${n}`, 'utf8')]));
mkdirSync('worker/generated', { recursive: true });
writeFileSync('worker/generated/collector-bundle.ts',
  '// Generated by scripts/build-collector.mjs. Do not edit; edit tools/collector and run npm run collector:build.\n' +
  `export const COLLECTOR_FILES: Record<string, string> = ${JSON.stringify(files)};\n`);
console.log('collector bundle:', names.length, 'files');
